type input struct { BaselineRuns int `json:"baselineRuns"`; BaselineMedianNS int64 `json:"baselineMedianNS"`; CandidateRuns int `json:"candidateRuns"`; CandidateMedianNS int64 `json:"candidateMedianNS"`; MinimumRuns int `json:"minimumRuns"` }
